const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body ?? item;
const receivedToken = headers['x-workflow-token'] ?? headers['X-Workflow-Token'];
if (!receivedToken || receivedToken !== $env.N8N_WORKFLOW_TOKEN) {
  throw new Error('Invalid x-workflow-token');
}
if (body.trigger !== 'lead.qualify_requested') {
  throw new Error(`Unexpected trigger: ${body.trigger ?? 'missing'}`);
}
if (!body.lead_id) {
  throw new Error('Missing lead_id');
}
if (!body.agent_run_id) {
  throw new Error('Missing agent_run_id');
}
return [{ json: { trigger: body.trigger, lead_id: body.lead_id, agent_run_id: body.agent_run_id } }];

const context = $input.first().json;
const triggerPayload = $('Validate Trigger').first().json;
const lead = context.lead ?? {};
const agentRunId = context.agent_run?.id ?? context.agent_run_id ?? triggerPayload.agent_run_id;
const pricing = Array.isArray(context.pricing_templates) ? context.pricing_templates : [];
const text = [lead.company_name, lead.contact_name, lead.contact_email, lead.enquiry_text].filter(Boolean).join(' ').toLowerCase();
const matches = pricing.filter((template) => [template.service, template.category, template.description].filter(Boolean).join(' ').toLowerCase().split(/\s+/).filter((token) => token.length > 3).some((token) => text.includes(token))).slice(0, 2);
const selected = (matches.length > 0 ? matches : pricing).slice(0, 2);
const urgencyScore = /urgent|asap|launch|deadline|this month|q[1-4]/i.test(text) ? 8 : 6;
const fitScore = selected.length > 0 ? 8 : 6;
const score = Math.min(95, Math.round((urgencyScore + fitScore) * 5));
const fallback = {
  lead_id: lead.id ?? triggerPayload.lead_id,
  agent_run_id: agentRunId,
  qualification_data: {
    urgency_score: urgencyScore,
    fit_score: fitScore,
    qualification_score: score,
    service_interest: selected.map((template) => template.service),
    budget_range: /\bhkd\b|\$|budget|retainer|monthly/i.test(text) ? 'HKD 50k-200k' : 'unknown',
    next_action: score >= 75 ? 'Schedule discovery call' : 'Request more info',
    reason: 'Deterministic staging fallback based on enquiry text and active pricing templates.',
    confidence: 0.64,
    human_review_required: true
  },
  lead_score: score,
  output_summary: `Fallback qualification scored ${lead.company_name ?? 'lead'} at ${score}.`,
  confidence_score: 0.64,
  model_used: 'deterministic-fallback'
};
const model = $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-6';
const openrouter_request = {
  model,
  messages: [
    { role: 'system', content: 'Return only JSON matching the ClientOps qualification writeback contract. Do not include markdown.' },
    { role: 'user', content: JSON.stringify({ context, required_fields: ['lead_id', 'agent_run_id', 'qualification_data', 'lead_score', 'output_summary', 'confidence_score', 'model_used'] }) }
  ],
  response_format: { type: 'json_object' }
};
return [{ json: { context, fallback, openrouter_request, openrouter_configured: Boolean($env.OPENROUTER_API_KEY) } }];

const prepared = $('Prepare Fallback / AI Request').first().json;
const fallback = prepared.fallback;
const response = $input.first()?.json ?? {};
let parsed;
const content = response.choices?.[0]?.message?.content;
if (typeof content === 'string') {
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    parsed = undefined;
  }
} else if (content && typeof content === 'object') {
  parsed = content;
}
const output = parsed && typeof parsed === 'object' ? { ...fallback, ...parsed } : fallback;
output.lead_id = output.lead_id || fallback.lead_id;
output.agent_run_id = output.agent_run_id || fallback.agent_run_id;
output.model_used = output.model_used || fallback.model_used;
return [{ json: output }];
